/*
Theme Name: SynFusion Premium Technology & Product Studio
Designer: Jules (Senior Frontend Engineer)
Description: Clean, responsive, high-converting product studio theme.
*/

/* Root Variables & Brand System */
:root {
  --color-primary: #145A32;
  --color-forest: #145A32;
  --color-emerald: #2E7D32;
  --color-olive: #6B8E23;
  --color-light-olive: #9ACD32;
  --color-cream: #F5F5DC;
  --color-cream-light: #FAF9F5;
  --color-dark: #121F16;
  --color-text: #1E293B;
  --color-text-muted: #64748B;
  --color-bg: #FFFFFF;
  --color-bg-alt: #F8FAF8;
  --color-border: #E2E8F0;

  --space-2xs: 4px;
  --space-xs: 8px;
  --space-sm: 12px;
  --space-md: 16px;
  --space-lg: 24px;
  --space-xl: 32px;
  --space-2xl: 48px;
  --space-3xl: 64px;
  --space-4xl: 96px;

  --font-size-xs: 0.8rem;
  --font-size-sm: 0.875rem;
  --font-size-base: 1rem;
  --font-size-lg: 1.125rem;
  --font-size-xl: 1.5rem;
  --font-size-2xl: 2.25rem;
  --font-size-3xl: 3rem;
  --font-size-hero: clamp(2.25rem, 5vw, 3.75rem);

  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 20px;
  --radius-xl: 28px;
  --radius-full: 9999px;

  --shadow-sm: 0 4px 12px rgba(20, 90, 50, 0.04);
  --shadow-md: 0 12px 32px rgba(20, 90, 50, 0.06);
  --shadow-lg: 0 24px 48px rgba(20, 90, 50, 0.10);

  --transition: all 0.25s cubic-bezier(0.25, 0.8, 0.25, 1);
}

[data-theme="dark"] {
  --color-bg: #090E0B;
  --color-bg-alt: #0F1612;
  --color-text: #F1F5F9;
  --color-text-muted: #94A3B8;
  --color-border: #1B2920;
  --color-cream: #223026;
  --color-cream-light: #142017;

  --shadow-sm: 0 4px 12px rgba(0, 0, 0, 0.3);
  --shadow-md: 0 12px 32px rgba(0, 0, 0, 0.4);
  --shadow-lg: 0 24px 48px rgba(0, 0, 0, 0.5);
}

/* Global Reset */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  font-size: 16px;
}

body {
  font-family: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  background-color: var(--color-bg);
  color: var(--color-text);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  transition: background-color 0.25s ease, color 0.25s ease;
  overflow-x: hidden;
}

@media (prefers-reduced-motion: reduce) {
  *, ::before, ::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

img, svg {
  max-width: 100%;
  height: auto;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
  transition: var(--transition);
}

button {
  font-family: inherit;
  background: none;
  border: none;
  cursor: pointer;
  outline: none;
}

/* Container System */
.container {
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 32px;
  width: 100%;
}

/* SVG Icon Inline Helper */
.icon-inline {
  display: inline-block;
  vertical-align: middle;
  flex-shrink: 0;
  stroke-width: 2;
}

/* Brand Logo Elements - Circular Treatment */
.brand-logo-frame {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: var(--color-bg-alt);
  border: 1px solid var(--color-border);
  overflow: hidden;
  flex-shrink: 0;
  transition: var(--transition);
  box-shadow: var(--shadow-sm);
}
.brand-logo-frame-nav {
  width: 44px;
  height: 44px;
  padding: 6px;
}
.brand-logo-frame-footer {
  width: 72px;
  height: 72px;
  padding: 10px;
  background: var(--color-cream-light);
  border: 2px solid var(--color-border);
}
.brand-logo-img {
  width: 100%;
  height: 100%;
  object-fit: contain;
  display: block;
}

/* Floating Navigation bar styles */
.navbar-wrapper {
  position: sticky;
  top: 0;
  z-index: 1000;
  background: rgba(255, 255, 255, 0.92);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border-bottom: 1px solid var(--color-border);
  transition: var(--transition);
}
[data-theme="dark"] .navbar-wrapper {
  background: rgba(9, 14, 11, 0.92);
}
.navbar-container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
}
.navbar-logo {
  display: flex;
  align-items: center;
  gap: 12px;
  text-decoration: none;
}
.navbar-links {
  display: flex;
  align-items: center;
  gap: 32px;
}
.navbar-link {
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--color-text-muted);
  position: relative;
  padding: 6px 0;
  transition: var(--transition);
}
.navbar-link:hover, .navbar-link.active {
  color: var(--color-forest);
}
[data-theme="dark"] .navbar-link:hover, [data-theme="dark"] .navbar-link.active {
  color: var(--color-light-olive);
}
.navbar-link::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  width: 0%;
  height: 2px;
  background-color: var(--color-emerald);
  border-radius: 2px;
  transition: var(--transition);
}
.navbar-link.active::after, .navbar-link:hover::after {
  width: 100%;
}
.navbar-actions {
  display: flex;
  align-items: center;
  gap: 16px;
}

/* Interactive Dark Mode Switch */
.theme-toggle {
  width: 42px;
  height: 42px;
  border-radius: 50%;
  background: var(--color-bg-alt);
  color: var(--color-text);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--color-border);
  cursor: pointer;
  transition: var(--transition);
}
.theme-toggle:hover {
  background: var(--color-border);
  border-color: var(--color-emerald);
  transform: scale(1.05);
}

/* Core Action Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 44px;
  padding: 10px 22px;
  border-radius: var(--radius-md);
  font-size: 0.95rem;
  font-weight: 600;
  line-height: 1.2;
  transition: var(--transition);
  cursor: pointer;
  text-decoration: none;
}
.btn:focus-visible {
  outline: 2px solid var(--color-emerald);
  outline-offset: 2px;
}
.btn-primary {
  background-color: var(--color-emerald);
  color: #FFFFFF;
  border: 1px solid var(--color-emerald);
}
.btn-primary:hover {
  background-color: var(--color-forest);
  border-color: var(--color-forest);
  transform: translateY(-2px);
}
.btn-secondary {
  background-color: var(--color-bg-alt);
  color: var(--color-text);
  border: 1px solid var(--color-border);
}
.btn-secondary:hover {
  background-color: var(--color-border);
  transform: translateY(-2px);
}

/* Burger Menu Mobile Trigger */
.burger-menu {
  display: none;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  gap: 5px;
  width: 42px;
  height: 42px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--color-border);
  background: var(--color-bg-alt);
}
.burger-bar {
  height: 2px;
  width: 20px;
  background-color: var(--color-text);
  border-radius: 2px;
  transition: var(--transition);
}

/* Hero Section */
.hero-section {
  padding: var(--space-4xl) 0 var(--space-3xl) 0;
  overflow: hidden;
  background: radial-gradient(circle at 85% 20%, rgba(46, 125, 50, 0.06) 0%, rgba(255, 255, 255, 0) 65%);
}
[data-theme="dark"] .hero-section {
  background: radial-gradient(circle at 85% 20%, rgba(154, 205, 50, 0.06) 0%, rgba(9, 14, 11, 0) 65%);
}
.hero-container {
  display: grid;
  grid-template-columns: 1.15fr 0.85fr;
  align-items: center;
  gap: var(--space-3xl);
}
.hero-eyebrow {
  font-size: var(--font-size-xs);
  font-weight: 800;
  letter-spacing: 0.12em;
  color: var(--color-emerald);
  text-transform: uppercase;
  margin-bottom: var(--space-md);
  display: inline-block;
}
.hero-title {
  font-size: var(--font-size-hero);
  font-weight: 850;
  line-height: 1.12;
  color: var(--color-text);
  letter-spacing: -0.035em;
  margin-bottom: var(--space-lg);
}
.hero-title span {
  color: var(--color-forest);
}
[data-theme="dark"] .hero-title span {
  color: var(--color-light-olive);
}
.hero-subtitle {
  font-size: 1.125rem;
  line-height: 1.6;
  color: var(--color-text-muted);
  margin-bottom: var(--space-xl);
  max-width: 540px;
}
.hero-buttons {
  display: flex;
  align-items: center;
  gap: var(--space-md);
  flex-wrap: wrap;
}
.hero-visual {
  position: relative;
  display: flex;
  justify-content: center;
  align-items: center;
}
.hero-mascot-wrapper {
  width: clamp(240px, 28vw, 360px);
  height: clamp(240px, 28vw, 360px);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
}
.mascot-img {
  width: 100%;
  height: 100%;
  object-fit: contain;
  display: block;
  filter: drop-shadow(0 16px 32px rgba(20, 90, 50, 0.12));
  animation: float-mascot 6s ease-in-out infinite;
}

/* Subtle Floating Badges in Hero */
.floating-badge {
  position: absolute;
  background: rgba(255, 255, 255, 0.92);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: var(--space-xs) var(--space-md);
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  box-shadow: var(--shadow-md);
  transition: var(--transition);
  z-index: 2;
}
[data-theme="dark"] .floating-badge {
  background: rgba(15, 22, 18, 0.92);
}
.floating-badge-1 {
  top: 5%;
  left: -2%;
  animation: float-badge-1 5s ease-in-out infinite;
}
.floating-badge-2 {
  bottom: 10%;
  right: -2%;
  animation: float-badge-2 5.5s ease-in-out infinite;
}
.badge-icon {
  width: 36px;
  height: 36px;
  border-radius: var(--radius-sm);
  background: var(--color-cream-light);
  border: 1px solid var(--color-border);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-emerald);
}
.badge-text {
  display: flex;
  flex-direction: column;
}
.badge-title {
  font-size: 0.85rem;
  font-weight: 700;
  color: var(--color-text);
}
.badge-sub {
  font-size: 0.75rem;
  color: var(--color-text-muted);
}

@keyframes float-mascot {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-10px); }
}
@keyframes float-badge-1 {
  0%, 100% { transform: translateY(0) rotate(-1.5deg); }
  50% { transform: translateY(-6px) rotate(1deg); }
}
@keyframes float-badge-2 {
  0%, 100% { transform: translateY(0) rotate(1.5deg); }
  50% { transform: translateY(-8px) rotate(-1deg); }
}

/* Stats Section */
.stats-section {
  padding: 32px 0;
  background-color: var(--color-cream-light);
  border-top: 1px solid var(--color-border);
  border-bottom: 1px solid var(--color-border);
}
.stats-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 32px;
  text-align: center;
}
.stat-card {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.stat-number {
  font-size: 2rem;
  font-weight: 850;
  color: var(--color-forest);
  letter-spacing: -0.02em;
}
[data-theme="dark"] .stat-number {
  color: var(--color-light-olive);
}
.stat-label {
  font-size: 0.8rem;
  color: var(--color-text-muted);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

/* Section Headers */
.section-header {
  text-align: center;
  max-width: 680px;
  margin: 0 auto 56px auto;
}
.section-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 14px;
  background-color: var(--color-cream-light);
  border: 1px solid var(--color-border);
  border-radius: 100px;
  font-size: 0.75rem;
  font-weight: 800;
  color: var(--color-forest);
  margin-bottom: 16px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}
[data-theme="dark"] .section-badge {
  color: var(--color-light-olive);
}
.section-title {
  font-size: 2.25rem;
  font-weight: 850;
  letter-spacing: -0.03em;
  color: var(--color-text);
  margin-bottom: 12px;
  line-height: 1.2;
}
.section-subtitle {
  font-size: 1.05rem;
  color: var(--color-text-muted);
  line-height: 1.5;
}

/* Products Showcase Section */
.products-section {
  padding: 96px 0;
  background-color: var(--color-bg);
}

/* Featured App Banner Layout */
.featured-showcase-card {
  background: var(--color-bg-alt);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-xl);
  padding: 48px;
  display: grid;
  grid-template-columns: 1.1fr 0.9fr;
  align-items: center;
  gap: 48px;
  box-shadow: var(--shadow-md);
  margin-bottom: 64px;
  position: relative;
  overflow: hidden;
}
.featured-badge-tag {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 14px;
  background: var(--color-emerald);
  color: #FFFFFF;
  border-radius: 100px;
  font-size: 0.75rem;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  margin-bottom: 20px;
}
.featured-app-header {
  display: flex;
  align-items: center;
  gap: 16px;
  margin-bottom: 16px;
}
.app-icon-lg {
  width: 64px;
  height: 64px;
  border-radius: var(--radius-md);
  background: var(--color-bg-alt);
  border: 1px solid var(--color-border);
  overflow: hidden;
  display: block;
  flex-shrink: 0;
  box-shadow: var(--shadow-sm);
}
.app-icon-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}
.app-title-lg {
  font-size: 1.85rem;
  font-weight: 850;
  color: var(--color-text);
  letter-spacing: -0.02em;
  line-height: 1.2;
}
.app-cat-tag {
  font-size: 0.8rem;
  font-weight: 700;
  color: var(--color-emerald);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}
.featured-app-desc {
  font-size: 1.05rem;
  color: var(--color-text-muted);
  margin-bottom: 24px;
  line-height: 1.6;
}
.featured-meta-row {
  display: flex;
  align-items: center;
  gap: 24px;
  margin-bottom: 32px;
  flex-wrap: wrap;
}
.meta-stat-item {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 0.9rem;
  font-weight: 700;
  color: var(--color-text);
}

/* Minimalist Smartphone Device Mockup (Aspect Ratio: 9 / 19.5) */
.mockup-container {
  display: flex;
  justify-content: center;
  align-items: center;
  width: 100%;
}
.phone-mockup {
  width: 100%;
  max-width: 240px;
  aspect-ratio: 9 / 19.5;
  background: #121F16;
  border: 8px solid #1B2920;
  border-radius: 36px;
  box-shadow: 0 20px 40px rgba(0, 0, 0, 0.15), 0 4px 12px rgba(20, 90, 50, 0.08);
  position: relative;
  overflow: hidden;
  display: block;
}
[data-theme="dark"] .phone-mockup {
  border-color: #27382D;
  box-shadow: 0 20px 40px rgba(0, 0, 0, 0.4);
}
.phone-mockup-sm {
  max-width: 180px;
  border-width: 6px;
  border-radius: 28px;
}
.phone-screen {
  width: 100%;
  height: 100%;
  border-radius: 26px;
  overflow: hidden;
  background: var(--color-bg-alt);
  display: block;
}
.phone-mockup-sm .phone-screen {
  border-radius: 20px;
}
.phone-screen-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: top;
  display: block;
}

/* Secondary Apps Grid */
.secondary-apps-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 32px;
}
.secondary-app-card {
  background: var(--color-bg-alt);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: 32px;
  display: flex;
  flex-direction: column;
  transition: var(--transition);
  box-shadow: var(--shadow-sm);
}
.secondary-app-card:hover {
  transform: translateY(-6px);
  box-shadow: var(--shadow-md);
  border-color: var(--color-emerald);
}
.card-top {
  display: flex;
  align-items: center;
  gap: 16px;
  margin-bottom: 20px;
}
.app-icon-md {
  width: 52px;
  height: 52px;
  border-radius: var(--radius-md);
  background: var(--color-bg-alt);
  border: 1px solid var(--color-border);
  overflow: hidden;
  display: block;
  flex-shrink: 0;
  box-shadow: var(--shadow-sm);
}
.app-title-md {
  font-size: 1.35rem;
  font-weight: 800;
  color: var(--color-text);
  line-height: 1.2;
}
.card-desc {
  font-size: 0.95rem;
  color: var(--color-text-muted);
  margin-bottom: 24px;
  flex: 1;
  line-height: 1.5;
}
.card-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 20px;
  font-size: 0.85rem;
  font-weight: 700;
  color: var(--color-text-muted);
}

/* Developer Profile Section */
.developer-section {
  padding: 80px 0;
  background: var(--color-bg-alt);
  border-top: 1px solid var(--color-border);
  border-bottom: 1px solid var(--color-border);
}
.developer-card {
  max-width: 800px;
  margin: 0 auto;
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-xl);
  padding: 40px;
  display: flex;
  align-items: center;
  gap: 36px;
  box-shadow: var(--shadow-sm);
}
.developer-avatar {
  width: 110px;
  height: 110px;
  border-radius: 50%;
  object-fit: cover;
  border: 3px solid var(--color-emerald);
  flex-shrink: 0;
  box-shadow: var(--shadow-md);
}
.developer-info {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.developer-eyebrow {
  font-size: 0.75rem;
  font-weight: 800;
  color: var(--color-emerald);
  text-transform: uppercase;
  letter-spacing: 0.1em;
}
.developer-name {
  font-size: 1.6rem;
  font-weight: 850;
  color: var(--color-text);
  letter-spacing: -0.02em;
}
.developer-bio {
  font-size: 0.95rem;
  color: var(--color-text-muted);
  line-height: 1.5;
  margin-bottom: 12px;
}
.developer-socials {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
}
.social-pill {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 8px 14px;
  min-height: 40px;
  border-radius: 100px;
  background: var(--color-bg-alt);
  border: 1px solid var(--color-border);
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--color-text);
  transition: var(--transition);
  text-decoration: none;
}
.social-pill:hover {
  border-color: var(--color-emerald);
  background: var(--color-cream-light);
  color: var(--color-forest);
  transform: translateY(-2px);
}
[data-theme="dark"] .social-pill:hover {
  color: var(--color-light-olive);
}

/* Dedicated SynFusion Brand Social Media Row */
.brand-social-section {
  padding: 48px 0;
  background: var(--color-bg);
  text-align: center;
}
.brand-social-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 20px;
}
.brand-social-handle {
  font-size: 0.9rem;
  font-weight: 800;
  color: var(--color-emerald);
  letter-spacing: 0.05em;
  text-transform: uppercase;
}
.brand-social-row {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  flex-wrap: wrap;
}
.brand-social-btn {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: var(--color-bg-alt);
  border: 1px solid var(--color-border);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: var(--color-text);
  transition: var(--transition);
  text-decoration: none;
}
.brand-social-btn:hover {
  background: var(--color-emerald);
  color: #FFFFFF;
  border-color: var(--color-emerald);
  transform: translateY(-3px);
}
.brand-social-btn:focus-visible {
  outline: 2px solid var(--color-emerald);
  outline-offset: 2px;
}

/* Final CTA Banner */
.cta-section {
  padding: 80px 0;
  background: var(--color-bg);
}
.cta-banner {
  background: linear-gradient(135deg, var(--color-forest) 0%, #0D3B1E 100%);
  border-radius: var(--radius-xl);
  padding: 64px 56px;
  display: grid;
  grid-template-columns: 1.1fr 0.9fr;
  align-items: center;
  gap: 48px;
  position: relative;
  overflow: hidden;
  box-shadow: var(--shadow-lg);
}
.cta-title {
  font-size: 2.5rem;
  font-weight: 850;
  color: #FFFFFF;
  letter-spacing: -0.03em;
  margin-bottom: 12px;
  line-height: 1.15;
}
.cta-desc {
  font-size: 1.05rem;
  color: #A5D6A7;
  margin-bottom: 28px;
  max-width: 480px;
}
.cta-buttons {
  display: flex;
  align-items: center;
  gap: 16px;
  flex-wrap: wrap;
}
.cta-mascot-wrapper {
  width: 220px;
  height: 220px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: center;
}

/* Contact Section */
.contact-section {
  padding: 80px 0;
  background: var(--color-bg-alt);
}
.contact-grid {
  display: grid;
  grid-template-columns: 1.2fr 0.8fr;
  gap: 64px;
}
.contact-form-container {
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: 40px;
  box-shadow: var(--shadow-sm);
}
.contact-form {
  display: flex;
  flex-direction: column;
  gap: 20px;
}
.form-group {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.form-label {
  font-size: 0.8rem;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--color-text-muted);
}
.form-input {
  padding: 12px 16px;
  border-radius: var(--radius-md);
  border: 1px solid var(--color-border);
  background: var(--color-bg-alt);
  color: var(--color-text);
  font-family: inherit;
  font-size: 0.95rem;
  transition: var(--transition);
}
.form-input:focus {
  border-color: var(--color-emerald);
  background: var(--color-bg);
  outline: none;
  box-shadow: 0 0 0 4px rgba(46, 125, 50, 0.1);
}
textarea.form-input {
  resize: vertical;
  min-height: 110px;
}

.contact-info-container {
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 32px;
}
.contact-card {
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.contact-card-label {
  font-size: 0.75rem;
  font-weight: 800;
  text-transform: uppercase;
  color: var(--color-emerald);
  letter-spacing: 0.08em;
}
.contact-card-val {
  font-size: 1.05rem;
  font-weight: 700;
  color: var(--color-text);
  display: flex;
  align-items: center;
  gap: 8px;
}

/* Restructured Footer */
.footer-section {
  padding: 64px 0 40px 0;
  background: var(--color-bg);
  border-top: 1px solid var(--color-border);
}
.footer-grid {
  display: grid;
  grid-template-columns: 1.2fr 1fr 1fr;
  gap: 48px;
  margin-bottom: 48px;
}
.footer-brand {
  display: flex;
  flex-direction: column;
  gap: 16px;
}
.footer-slogan {
  font-size: 0.9rem;
  color: var(--color-text-muted);
}
.footer-nav {
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.footer-nav-title {
  font-size: 0.75rem;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--color-text-muted);
  margin-bottom: 4px;
}
.footer-nav-link {
  font-size: 0.9rem;
  color: var(--color-text);
  text-decoration: none;
}
.footer-nav-link:hover {
  color: var(--color-emerald);
}
.footer-social-row {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-top: 8px;
}
.footer-social-link {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: var(--color-bg-alt);
  border: 1px solid var(--color-border);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: var(--color-text);
  transition: var(--transition);
  text-decoration: none;
}
.footer-social-link:hover {
  background: var(--color-emerald);
  color: #FFFFFF;
  border-color: var(--color-emerald);
  transform: translateY(-2px);
}
.footer-bottom {
  border-top: 1px solid var(--color-border);
  padding-top: 28px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 16px;
  font-size: 0.85rem;
  color: var(--color-text-muted);
}

/* Responsive Breakpoints */
@media (max-width: 1024px) {
  .container {
    padding: 0 24px;
  }
  .hero-container {
    grid-template-columns: 1fr;
    text-align: center;
    gap: 40px;
  }
  .hero-left {
    display: flex;
    flex-direction: column;
    align-items: center;
  }
  .hero-subtitle {
    margin-left: auto;
    margin-right: auto;
  }
  .featured-showcase-card {
    grid-template-columns: 1fr;
    padding: 36px;
    gap: 36px;
    text-align: center;
  }
  .featured-app-header {
    justify-content: center;
    flex-direction: column;
  }
  .featured-meta-row {
    justify-content: center;
  }
  .cta-banner {
    grid-template-columns: 1fr;
    padding: 40px 32px;
    text-align: center;
  }
  .cta-buttons {
    justify-content: center;
  }
  .contact-grid {
    grid-template-columns: 1fr;
    gap: 40px;
  }
  .developer-card {
    flex-direction: column;
    text-align: center;
  }
  .developer-socials {
    justify-content: center;
  }
}

@media (max-width: 768px) {
  .container {
    padding: 0 20px;
  }
  .navbar-actions .btn {
    display: none;
  }
  .navbar-links {
    display: flex;
    position: absolute;
    top: 72px;
    left: 0;
    right: 0;
    background: var(--color-bg);
    border-bottom: 1px solid var(--color-border);
    box-shadow: var(--shadow-md);
    flex-direction: column;
    padding: 24px;
    gap: 16px;
    text-align: center;
    opacity: 0;
    visibility: hidden;
    transform: translateY(-12px);
    transition: opacity 0.25s ease, transform 0.25s ease, visibility 0.25s;
    pointer-events: none;
  }
  .navbar-links.active {
    opacity: 1;
    visibility: visible;
    transform: translateY(0);
    pointer-events: auto;
  }
  .navbar-link::after {
    display: none;
  }
  .burger-menu {
    display: flex;
  }
  .stats-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: 24px;
  }
  .secondary-apps-grid {
    grid-template-columns: 1fr;
  }
  .secondary-app-card > div {
    grid-template-columns: 1fr !important;
  }
  .footer-grid {
    grid-template-columns: 1fr;
    gap: 32px;
  }
}

@media (max-width: 480px) {
  .container {
    padding: 0 16px;
  }
  .hero-section, .products-section, .developer-section, .cta-section, .contact-section {
    padding: 48px 0;
  }
  .hero-buttons, .cta-buttons {
    flex-direction: column;
    width: 100%;
  }
  .hero-buttons .btn, .cta-buttons .btn {
    width: 100%;
  }
  .floating-badge-1 {
    left: 0;
    top: -10px;
  }
  .floating-badge-2 {
    right: 0;
    bottom: -10px;
  }
  .stats-grid {
    grid-template-columns: 1fr;
  }
  .featured-showcase-card {
    padding: 24px 16px;
  }
  .contact-form-container {
    padding: 24px 16px;
  }
  .footer-bottom {
    flex-direction: column;
    text-align: center;
  }
}

body.script:
//
// Theme Initializer to prevent flashing
(function() {
  const savedTheme = localStorage.getItem('theme');
  if (savedTheme) {
    document.documentElement.setAttribute('data-theme', savedTheme);
  } else if (window.matchMedia('(prefers-color-scheme: dark)').matches) {
    document.documentElement.setAttribute('data-theme', 'dark');
  }
})();

// Dark Mode Toggle Logic
const themeToggleBtn = document.getElementById('themeToggle');
const lightIcon = themeToggleBtn.querySelector('.light-icon');
const darkIcon = themeToggleBtn.querySelector('.dark-icon');

function updateToggleIcons(theme) {
  if (theme === 'dark') {
    lightIcon.style.display = 'none';
    darkIcon.style.display = 'inline';
  } else {
    lightIcon.style.display = 'inline';
    darkIcon.style.display = 'none';
  }
}

const currentTheme = document.documentElement.getAttribute('data-theme') || 'light';
updateToggleIcons(currentTheme);

themeToggleBtn.addEventListener('click', () => {
  const activeTheme = document.documentElement.getAttribute('data-theme') === 'dark' ? 'light' : 'dark';
  document.documentElement.setAttribute('data-theme', activeTheme);
  localStorage.setItem('theme', activeTheme);
  updateToggleIcons(activeTheme);
});

// Mobile Hamburger Dropdown Menu
const burgerMenu = document.getElementById('burgerMenu');
const navbarLinks = document.getElementById('navbarLinks');

if (burgerMenu && navbarLinks) {
  burgerMenu.addEventListener('click', () => {
    navbarLinks.classList.toggle('active');
    const bars = burgerMenu.querySelectorAll('.burger-bar');
    if (navbarLinks.classList.contains('active')) {
      bars[0].style.transform = 'rotate(45deg) translate(5px, 5px)';
      bars[1].style.opacity = '0';
      bars[2].style.transform = 'rotate(-45deg) translate(5px, -5px)';
    } else {
      bars[0].style.transform = 'none';
      bars[1].style.opacity = '1';
      bars[2].style.transform = 'none';
    }
  });

  const navLinksArray = document.querySelectorAll('.navbar-link');
  navLinksArray.forEach(link => {
    link.addEventListener('click', () => {
      navbarLinks.classList.remove('active');
      const bars = burgerMenu.querySelectorAll('.burger-bar');
      bars[0].style.transform = 'none';
      bars[1].style.opacity = '1';
      bars[2].style.transform = 'none';

      navLinksArray.forEach(l => l.classList.remove('active'));
      link.classList.add('active');
    });
  });
}

// Scroll Navbar Shadow Toggle
window.addEventListener('scroll', () => {
  const header = document.querySelector('.navbar-wrapper');
  if (header) {
    if (window.scrollY > 20) {
      header.style.boxShadow = 'var(--shadow-sm)';
    } else {
      header.style.boxShadow = 'none';
    }
  }
});

// Contact Form Handler
function handleContactSubmit(event) {
  event.preventDefault();
  const name = document.getElementById('contactName').value;
  const email = document.getElementById('contactEmail').value;

  alert(`Thank you, ${name}! Your message has been sent. We will reply to ${email} as soon as possible.`);
  document.getElementById('contactForm').reset();
}
//
